/**
 * DTO - Authentication type constants for hybrid authentication
 * Distinguishes cookie-based (web) from JWT header-based (mobile) auth strategy
 */
/** ENUM */
/* AUTH TYPE */
export const enum AuthType {
    // web browsers use HttpOnly cookies set and managed by the server
    COOKIE = "COOKIE",
    // native mobile apps send JWT in Authorization header
    HEADER = "HEADER"
};

/**
 * @file UserErrorMessages.ts
 * Application domain error constants.
 */

export enum UserErrorMessage {
    /* AUTHENTICATION ERRORS */
    INVALID_CREDENTIALS = "Invalid email or password.",
    USER_NOT_FOUND = "No user found with this email.",
    ACCOUNT_LOCKED = "Account is temporarily locked.",

    /* VALIDATION ERRORS */
    MISSING_FIELDS = "Please fill in all required fields.",
    REFRESH_TOKEN_NOT_AVAILABLE = 'No refresh token available',

    /* STORAGE ERRORS */
    SECURE_STORAGE_FAILED = 'Secure storage failed'
}

import { Injectable } from '@angular/core';

/**
 * Service - Detects whether the app runs in a native mobile container or a web browser
 * Supports Capacitor, Cordova, and user-agent-based detection
 */
@Injectable({
    providedIn: 'root'
})
export class PlatformDetectionService {

    // toggle to also include mobile user-agent strings in detection
    private readonly ENABLE_USER_AGENT_DETECTION = true;

    /** PUBLIC */
    /* IS MOBILE */
    isMobile(): boolean {
        const isNativeApp = this.isCapacitor() || this.isCordova();

        if (this.ENABLE_USER_AGENT_DETECTION) {
            return isNativeApp || this.isMobileUserAgent();
        }

        return isNativeApp;
    }

    /* IS WEB */
    isWeb(): boolean {
        return !this.isMobile();
    }

    /* GET PLATFORM */
    getPlatform(): 'web' | 'mobile' {
        return this.isMobile() ? 'mobile' : 'web';
    }

    /** PRIVATE */
    /* IS CAPACITOR */
    private isCapacitor(): boolean {
        return !!(window as any)?.Capacitor;
    }

    /* IS CORDOVA */
    private isCordova(): boolean {
        return !!(window as any)?.cordova;
    }

    /* IS MOBILE USER AGENT */
    private isMobileUserAgent(): boolean {
        const userAgent = navigator.userAgent.toLowerCase();
        const mobileKeywords = [
            'android', 'iphone', 'ipad', 'ipod', 'blackberry',
            'windows phone', 'mobile', 'tablet'
        ];
        return mobileKeywords.some(keyword => userAgent.includes(keyword));
    }
}

import { Injectable } from '@angular/core';
import { PlatformDetectionService } from './platformDetection.service';
import { UserDTO } from '../models/User';
import { StorageServiceInterface } from './servicesImpl/storageServiceInterface';
import { LoginResponse } from '../DTO/LoginResponse';
import { UserErrorMessage } from '../constants/userErrorMessage';

/**
 * Service - Platform-aware token storage for mobile JWT flows
 * On mobile: uses native SecureStorage (Keychain/Keystore)
 * On web: cookies are handled by the browser — this service is not used
 */
@Injectable({
    providedIn: 'root'
})
export class AdaptiveStorageService implements StorageServiceInterface {

    private readonly JWT_KEY_NAME = 'auth_jwt_token';
    private readonly JWT_REFRESH_KEY_NAME = 'auth_refresh_token';
    private readonly AUTH_STATE_KEY_NAME = 'authState';
    // DEV_MODE allows localStorage fallback when native secure storage is unavailable
    private readonly DEV_MODE = true;

    constructor(private platformDetection: PlatformDetectionService) { }

    /** PUBLIC */
    /* GET AUTH TOKEN */
    async getAuthToken(): Promise<string | null> {
        return await this.getMobileToken();
    }

    /* SET AUTH TOKEN */
    async setAuthToken(token: string): Promise<void> {
        return await this.storeMobileToken(token);
    }

    /* GET AUTH REFRESH TOKEN */
    async getAuthRefreshToken(): Promise<string | null> {
        return await this.getMobileRefreshToken();
    }

    /* SET AUTH REFRESH TOKEN */
    async setAuthRefreshToken(token: string): Promise<void> {
        return await this.storeMobileRefreshToken(token);
    }

    /* SET AUTH STATE */
    // stores login result in localStorage so isLoggedIn() works across page reloads
    setAuthState(loginResponse: LoginResponse): void {
        localStorage.setItem(this.AUTH_STATE_KEY_NAME, JSON.stringify({
            isLoggedIn: loginResponse.success,
            authType: loginResponse.authType,
            user: loginResponse.user
        }));
    }

    /* GET AUTH STATE */
    getAuthState(): boolean {
        const authStateString = localStorage.getItem(this.AUTH_STATE_KEY_NAME);
        if (!authStateString) return false;
        try {
            const authState = JSON.parse(authStateString);
            return authState.isLoggedIn;
        } catch (error) {
            return false;
        }
    }

    /* GET AUTH STATE USER */
    getAuthStateUser(): UserDTO | null {
        const authStateString = localStorage.getItem(this.AUTH_STATE_KEY_NAME);
        if (!authStateString) return null;
        try {
            const authState = JSON.parse(authStateString);
            return authState.user || null;
        } catch (error) {
            return null;
        }
    }

    /* CLEAR AUTH DATA */
    async clearAuthData(): Promise<void> {
        localStorage.removeItem(this.AUTH_STATE_KEY_NAME);
        if (this.platformDetection.isMobile()) {
            await this.clearMobileStorage();
        }
    }

    /** PRIVATE */
    /* STORE MOBILE TOKEN */
    private async storeMobileToken(token: string): Promise<void> {
        if ((window as any).SecureStorage) {
            try {
                await (window as any).SecureStorage.set(this.JWT_KEY_NAME, token);
            } catch (error) {
                throw new Error(UserErrorMessage.SECURE_STORAGE_FAILED, { cause: error });
            }
        } else if (this.DEV_MODE) {
            localStorage.setItem(this.JWT_KEY_NAME, token);
        }
    }

    /* GET MOBILE TOKEN */
    private async getMobileToken(): Promise<string | null> {
        if ((window as any).SecureStorage) {
            try {
                return await (window as any).SecureStorage.get(this.JWT_KEY_NAME);
            } catch (error) {
                console.error(UserErrorMessage.SECURE_STORAGE_FAILED, error);
                return null;
            }
        } else if (this.DEV_MODE) {
            return localStorage.getItem(this.JWT_KEY_NAME);
        }
        return null;
    }

    /* STORE MOBILE REFRESH TOKEN */
    private async storeMobileRefreshToken(token: string): Promise<void> {
        if ((window as any).SecureStorage) {
            try {
                await (window as any).SecureStorage.set(this.JWT_REFRESH_KEY_NAME, token);
            } catch (error) {
                throw new Error(UserErrorMessage.SECURE_STORAGE_FAILED, { cause: error });
            }
        } else if (this.DEV_MODE) {
            localStorage.setItem(this.JWT_REFRESH_KEY_NAME, token);
        }
    }

    /* GET MOBILE REFRESH TOKEN */
    private async getMobileRefreshToken(): Promise<string | null> {
        if ((window as any).SecureStorage) {
            try {
                return await (window as any).SecureStorage.get(this.JWT_REFRESH_KEY_NAME);
            } catch (error) {
                console.error(UserErrorMessage.SECURE_STORAGE_FAILED, error);
                return null;
            }
        } else if (this.DEV_MODE) {
            return localStorage.getItem(this.JWT_REFRESH_KEY_NAME);
        }
        return null;
    }

    /* CLEAR MOBILE STORAGE */
    private async clearMobileStorage(): Promise<void> {
        if ((window as any).SecureStorage) {
            await (window as any).SecureStorage.remove(this.JWT_KEY_NAME);
            await (window as any).SecureStorage.remove(this.JWT_REFRESH_KEY_NAME);
        } else if (this.DEV_MODE) {
            localStorage.removeItem(this.JWT_KEY_NAME);
            localStorage.removeItem(this.JWT_REFRESH_KEY_NAME);
        }
    }
}

import { Injectable } from '@angular/core';
import { HttpClient, HttpResponse } from '@angular/common/http';
import { Router } from '@angular/router';
import { Observable, from, of, throwError } from 'rxjs';
import { map, switchMap, finalize } from 'rxjs/operators';

import { UserDTO } from '../models/User';
import { MessageResponse } from '../DTO/MessageResponse';
import { Login } from '../DTO/Login';
import { LoginResponse } from '../DTO/LoginResponse';
import { AuthType } from '../DTO/AuthType';
import { UserServiceInterface } from './servicesImpl/userServicesInterface';
import { PlatformDetectionService } from './platformDetection.service';
import { AdaptiveStorageService } from './adaptiveStorage.service';
import { UserErrorMessage } from '../constants/userErrorMessage';

/**
 * Service - Handles user authentication, session management and token refresh
 * Platform-aware: uses cookies on web and JWT headers on mobile
 */
@Injectable({
  providedIn: 'root'
})
export class UserService implements UserServiceInterface {
  private readonly apiUrl = '/api';

  constructor(
    private httpClient: HttpClient,
    private platformDetection: PlatformDetectionService,
    private adaptiveStorage: AdaptiveStorageService,
    private router: Router
  ) { }

  /** PUBLIC */
  /* REGISTER */
  register(userDTO: UserDTO): Observable<MessageResponse> {
    if (!userDTO?.login || !userDTO?.password) {
      throw new Error(UserErrorMessage.MISSING_FIELDS);
    }
    return this.httpClient.post<MessageResponse>(`${this.apiUrl}/register`, userDTO);
  }

  /* LOGIN */
  login(login: Login): Observable<LoginResponse> {
    if (!login?.login || !login?.password) {
      throw new Error(UserErrorMessage.MISSING_FIELDS);
    }

    const loginPayload: Login = {
      ...login,
      authType: this.platformDetection.isMobile() ? AuthType.HEADER : AuthType.COOKIE
    };

    return this.httpClient.post<LoginResponse>(`${this.apiUrl}/login`, loginPayload, { observe: 'response' }).pipe(
      switchMap((httpResponse: HttpResponse<LoginResponse>) => from(this.processLoginResponse(httpResponse)))
    );
  }

  /* LOGOUT */
  logout(): void {
    this.httpClient.post<MessageResponse>(`${this.apiUrl}/logout`, {}).pipe(
      finalize(() => {
        // cleanup always runs, even if the logout API call fails
        this.adaptiveStorage.clearAuthData();
        this.router.navigate(['/home']);
      })
    ).subscribe({
      error: (error) => console.error('Logout API call failed, but local session cleared', error)
    });
  }

  /* GET CURRENT USER */
  getCurrentUser(): UserDTO | null {
    return this.adaptiveStorage.getAuthStateUser();
  }

  /* IS LOGGED IN */
  isLoggedIn(): boolean {
    return this.adaptiveStorage.getAuthState();
  }

  /* GET AUTH TOKEN */
  async getAuthToken(): Promise<string | null> {
    return this.platformDetection.isMobile() ? await this.adaptiveStorage.getAuthToken() : null;
  }

  /* SET AUTH TOKEN */
  async setAuthToken(token: string): Promise<void> {
    if (this.platformDetection.isMobile()) {
      await this.adaptiveStorage.setAuthToken(token);
    }
  }

  /* REFRESH ACCESS TOKEN */
  refreshAccessToken(): Observable<MessageResponse> {
    const isMobile = this.platformDetection.isMobile();

    if (!isMobile) {
      return this.httpClient.post<MessageResponse>(`${this.apiUrl}/refresh`, {});
    }

    return from(this.adaptiveStorage.getAuthRefreshToken()).pipe(
      switchMap((refreshToken: string | null) => {
        if (!refreshToken) return throwError(() => new Error(UserErrorMessage.REFRESH_TOKEN_NOT_AVAILABLE));

        return this.httpClient.post<MessageResponse>(
          `${this.apiUrl}/refresh`,
          { refreshToken },
          { observe: 'response' }
        );
      }),
      switchMap((httpResponse: HttpResponse<MessageResponse>) => {
        const token = this.extractTokenFromResponse(httpResponse);
        if (token) {
          return from(this.adaptiveStorage.setAuthToken(token)).pipe(
            map(() => httpResponse.body as MessageResponse)
          );
        }
        return of(httpResponse.body as MessageResponse);
      })
    );
  }

  /** PRIVATE */
  /* PROCESS LOGIN RESPONSE */
  private async processLoginResponse(httpResponse: HttpResponse<LoginResponse>): Promise<LoginResponse> {
    const response = httpResponse.body as LoginResponse;
    if (!response || !response.success) return response;

    this.adaptiveStorage.setAuthState(response);

    if (response.authType === AuthType.HEADER && this.platformDetection.isMobile()) {
      if (response.refreshToken) {
        await this.adaptiveStorage.setAuthRefreshToken(response.refreshToken);
      }

      const token = this.extractTokenFromResponse(httpResponse);
      if (token) {
        await this.adaptiveStorage.setAuthToken(token);
      }
    }

    return response;
  }

  /* EXTRACT TOKEN FROM RESPONSE */
  private extractTokenFromResponse(response: HttpResponse<any>): string | null {
    const authHeader = response.headers.get('Authorization');
    if (authHeader && authHeader.startsWith('Bearer ')) {
      return authHeader.substring(7);
    }
    return null;
  }
}

/**
 * @file httpErrorMessage.ts
 * HTTP status error message constants — used by ErrorService and AuthInterceptor
 */

export enum HttpErrorMessage {
    /* NETWORK */
    NETWORK = 'Unable to connect to the server. Please check your network.',

    /* AUTH */
    UNAUTHORIZED = 'Unauthorized. Please log in again.',
    SESSION_EXPIRED = 'Session expired. Please log in again.',

    /* ACCESS */
    FORBIDDEN = 'Access denied.',
    NOT_FOUND = 'Service not found.',

    /* SERVER */
    SERVER_ERROR = 'Internal server error. Please try again later.',
    UNKNOWN = 'An unexpected error occurred. Please try again.'
}

import { Injectable } from '@angular/core';
import { HttpErrorResponse } from "@angular/common/http";
import { InfoMessage } from '../constants/InfoMessage';
import { HttpErrorMessage } from '../constants/httpErrorMessage';

/**
 * Service - Centralizes HTTP error handling
 * Converts HTTP status codes into user-friendly messages for the template
 */
type ErrorServiceInterface = {
    handleError(err: HttpErrorResponse, infoMessage: InfoMessage): void;
}

@Injectable({
    providedIn: 'root'
})
export class ErrorService implements ErrorServiceInterface {

    /** PUBLIC */
    /* HANDLE ERROR */
    handleError(err: HttpErrorResponse, infoMessage: InfoMessage): void {
        const message = this.getErrorMessage(err);

        infoMessage.message = message;
        infoMessage.error = true;
    }

    /** PRIVATE */
    /* GET ERROR MESSAGE */
    private getErrorMessage(err: HttpErrorResponse): string {
        if (err.error?.message) {
            return err.error.message;
        }

        switch (err.status) {
            case 0: return HttpErrorMessage.NETWORK;
            case 401: return HttpErrorMessage.UNAUTHORIZED;
            case 403: return HttpErrorMessage.FORBIDDEN;
            case 404: return HttpErrorMessage.NOT_FOUND;
            case 500: return HttpErrorMessage.SERVER_ERROR;
            default: return HttpErrorMessage.UNKNOWN;
        }
    }
}

import { NgModule } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';

// Angular CDK imports
import { OverlayModule } from '@angular/cdk/overlay';
import { CdkTreeModule } from '@angular/cdk/tree';
import { PortalModule } from '@angular/cdk/portal';

// Angular Material imports (alphabetical order)
import { MatAutocompleteModule } from '@angular/material/autocomplete';
import { MatButtonModule } from '@angular/material/button';
import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { MatCardModule } from '@angular/material/card';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatChipsModule } from '@angular/material/chips';
import { MatRippleModule } from '@angular/material/core';
import { MatDividerModule } from '@angular/material/divider';
import { MatExpansionModule } from '@angular/material/expansion';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';
import { MatInputModule } from '@angular/material/input';
import { MatListModule } from '@angular/material/list';
import { MatMenuModule } from '@angular/material/menu';
import { MatPaginatorModule } from '@angular/material/paginator';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSelectModule } from '@angular/material/select';
