import { MatTreeModule } from '@angular/material/tree';

/**
 * Centralized Angular Material components module
 * Imports and exports all necessary Material Design components and Angular CDK modules
 * for consistent UI throughout the application
 */

// Core modules (Forms and CDK)
const coreModules = [
  ReactiveFormsModule,
  OverlayModule,
  CdkTreeModule,
  PortalModule
];

// Material Design components (alphabetical order)
const materialComponents = [
  MatAutocompleteModule,
  MatButtonModule,
  MatButtonToggleModule,
  MatCardModule,
  MatCheckboxModule,
  MatChipsModule,
  MatDividerModule,
  MatExpansionModule,
  MatFormFieldModule,
  MatIconModule,
  MatInputModule,
  MatListModule,
  MatMenuModule,
  MatPaginatorModule,
  MatProgressSpinnerModule,
  MatRippleModule,
  MatSelectModule,
  MatSidenavModule,
  MatSnackBarModule,
  MatSortModule,
  MatTableModule,
  MatTabsModule,
  MatToolbarModule,
  MatTreeModule
];

// Combined modules for export
const allMaterialModules = [
  ...coreModules,
  ...materialComponents
];

/**
 * Material Design module providing all necessary Angular Material components
 * Centralizes material imports to avoid duplication across components
 */
@NgModule({
  imports: allMaterialModules,
  exports: allMaterialModules
})
export class MaterialModule {

  constructor() {
    console.log('MaterialModule initialized - All Angular Material components loaded');
  }
}

/**
 * @file appNotification.ts
 * Application notification and success message constants
 * Static messages use an enum; dynamic messages (with names) use helper functions
 */

/* STATIC NOTIFICATIONS */
export enum AppNotification {
    /* AUTH */
    REGISTRATION_SUCCESS = 'Registration successful! Please log in.',

    /* STUDENT */
    STUDENT_DELETED = 'Student deleted successfully'
}

/* DYNAMIC NOTIFICATIONS */
// functions are used when the message includes runtime values (user name, student name, etc.)
export const AppNotificationMessage = {
    /* AUTH */
    REGISTER_WELCOME: (login: string) =>
        `Hi, ${login}! You are now registered, you can now log in!`,

    /* STUDENT */
    STUDENT_CREATED: (firstName: string, lastName: string) =>
        `Student ${firstName} ${lastName} created successfully`,

    STUDENT_UPDATED: (firstName: string, lastName: string) =>
        `Student ${firstName} ${lastName} has been updated successfully`
};

import { Component, DestroyRef, inject, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { HttpErrorResponse } from '@angular/common/http';

import { UserService } from '../../core/service/user.service';
import { UserDTO } from '../../core/models/User';
import { ErrorService } from '../../core/service/error.service';
import { MaterialModule } from '../../shared/material.module';
import { InfoMessage } from '../../core/constants/InfoMessage';
import { AppNotification, AppNotificationMessage } from '../../core/constants/appNotification';

/**
 * Component - Registration page that creates a new user account
 * Redirects to /login with a success message after registration
 */
@Component({
  selector: 'app-register',
  standalone: true,
  imports: [MaterialModule, ReactiveFormsModule],
  templateUrl: './register.component.html',
  styleUrls: ['../../../styles.css']
})
export class RegisterComponent implements OnInit {

  private userService = inject(UserService);
  private formBuilder = inject(FormBuilder);
  private destroyRef = inject(DestroyRef);
  private errorService = inject(ErrorService);
  private router = inject(Router);

  registerForm!: FormGroup;
  submitted: boolean = false;
  infoMessage: InfoMessage = { message: '', error: false };
  passwordVisible: boolean = false;

  constructor() { }

  /** LIFECYCLE */
  /* NG ON INIT */
  ngOnInit(): void {
    this.initializeForm();
  }

  /** GETTER */
  /* FORM */
  get form() {
    return this.registerForm.controls;
  }

  /** PUBLIC */
  /* TOGGLE PASSWORD VISIBILITY */
  togglePasswordVisibility(): void {
    this.passwordVisible = !this.passwordVisible;
  }

  /* ON SUBMIT */
  onSubmit(): void {
    this.submitted = true;

    if (this.registerForm.invalid) return;

    const registerUser: UserDTO = this.registerForm.value;

    this.userService.register(registerUser)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.infoMessage = {
            message: AppNotificationMessage.REGISTER_WELCOME(registerUser.login),
            error: false
          };

          setTimeout(() => {
            this.router.navigate(['/login'], {
              queryParams: {
                msg: AppNotification.REGISTRATION_SUCCESS,
                error: 'false'
              }
            });
          }, 2000);
        },
        error: (err: HttpErrorResponse) => this.errorService.handleError(err, this.infoMessage)
      });
  }

  /* ON RESET */
  onReset(): void {
    this.submitted = false;
    this.registerForm.reset();
  }

  /** PRIVATE */
  /* INITIALIZE FORM */
  private initializeForm(): void {
    this.registerForm = this.formBuilder.group({
      firstName: ['', [
        Validators.required,
        Validators.minLength(2),
        Validators.maxLength(50),
        Validators.pattern("^[a-zA-ZÀ-ÿ\\s'-]+$")
      ]],
      lastName: ['', [
        Validators.required,
        Validators.minLength(2),
        Validators.maxLength(50),
        Validators.pattern("^[a-zA-ZÀ-ÿ\\s'-]+$")
      ]],
      login: ['', [
        Validators.required,
        Validators.email,
        Validators.maxLength(100)
      ]],
      password: ['', [
        Validators.required,
        Validators.minLength(8),
        Validators.maxLength(128),
        Validators.pattern("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[@$!%*?&.-_])[A-Za-z\\d@$!%*?&.-_]+$")
      ]]
    });
  }
}

import { Component, DestroyRef, inject, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { HttpErrorResponse } from '@angular/common/http';

import { MaterialModule } from '../../shared/material.module';
import { UserService } from '../../core/service/user.service';
import { Login } from '../../core/DTO/Login';
import { InfoMessage } from '../../core/constants/InfoMessage';
import { ErrorService } from '../../core/service/error.service';

/**
 * Component - Login page with form validation and query-params message display
 * Redirects to returnUrl or /studentList after successful authentication
 */
@Component({
  selector: 'app-login',
  standalone: true,
  imports: [MaterialModule, ReactiveFormsModule],
  templateUrl: './login.component.html',
  styleUrls: ['../../../styles.css']
})
export class LoginComponent implements OnInit {

  private userService = inject(UserService);
  private formBuilder = inject(FormBuilder);
  private destroyRef = inject(DestroyRef);
  private router = inject(Router);
  private route = inject(ActivatedRoute);
  private errorService = inject(ErrorService);

  loginForm!: FormGroup;
  submitted: boolean = false;
  infoMessage: InfoMessage = { message: '', error: false };
  passwordVisible: boolean = false;

  constructor() { }

  /** LIFECYCLE */
  /* NG ON INIT */
  ngOnInit(): void {
    this.initializeForm();
    this.checkQueryParams();
  }

  /** GETTER */
  /* FORM */
  get form() {
    return this.loginForm.controls;
  }

  /** PUBLIC */
  /* ON SUBMIT */
  onSubmit(): void {
    this.submitted = true;
    this.infoMessage = { message: '', error: false };

    if (this.loginForm.invalid) return;

    const credentials: Login = this.loginForm.value;

    this.userService.login(credentials)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.infoMessage = { message: `Hi, ${credentials.login}! You are now logged in!`, error: false };

          setTimeout(() => {
            const returnUrl = this.route.snapshot.queryParams['returnUrl'] || '/studentList';
            this.router.navigateByUrl(returnUrl);
          }, 5000);
        },
        error: (err: HttpErrorResponse) => this.errorService.handleError(err, this.infoMessage)
      });
  }

  /* ON RESET */
  onReset(): void {
    this.submitted = false;
    this.infoMessage = { message: '', error: false };
    this.loginForm.reset();
  }

  /* TOGGLE PASSWORD VISIBILITY */
  togglePasswordVisibility(): void {
    this.passwordVisible = !this.passwordVisible;
  }

  /** PRIVATE */
  /* INITIALIZE FORM */
  private initializeForm(): void {
    this.loginForm = this.formBuilder.group({
      login: ['', [Validators.required, Validators.email, Validators.maxLength(100)]],
      password: ['', [
        Validators.required,
        Validators.minLength(8),
        Validators.maxLength(128),
        Validators.pattern("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[@$!%*?&.-_])[A-Za-z\\d@$!%*?&.-_]+$")
      ]],
      rememberMe: [true]
    });
  }

  /* CHECK QUERY PARAMS */
  // read msg/error params passed by register or session-expired redirect
  private checkQueryParams(): void {
    this.route.queryParams
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(params => {
        const msg = params['msg'];
        const error = params['error'];

        if (msg) {
          this.infoMessage = {
            message: msg,
            error: error === 'true'
          };
        }
      });
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Student, StudentDto } from '../models/Student';
import { StudentServiceInterface } from './servicesImpl/studentServicesInterface';

/**
 * Service - Manages student CRUD operations via HTTP
 * All methods return Observables so the component can subscribe and react
 */
@Injectable({
  providedIn: 'root'
})
export class StudentService implements StudentServiceInterface {
  private readonly apiUrl = '/api/students';

  constructor(private httpClient: HttpClient) { }

  /** PUBLIC */
  /* GET ALL STUDENTS */
  getAllStudents(): Observable<Student[]> {
    return this.httpClient.get<Student[]>(this.apiUrl);
  }

  /* GET STUDENT BY ID */
  getStudentById(id: number): Observable<Student> {
    return this.httpClient.get<Student>(`${this.apiUrl}/${id}`);
  }

  /* CREATE STUDENT */
  createStudent(student: StudentDto): Observable<Student> {
    return this.httpClient.post<Student>(this.apiUrl, student);
  }

  /* UPDATE STUDENT */
  updateStudent(id: number, student: StudentDto): Observable<Student> {
    return this.httpClient.put<Student>(`${this.apiUrl}/${id}`, student);
  }

  /* DELETE STUDENT */
  deleteStudent(id: number): Observable<void> {
    return this.httpClient.delete<void>(`${this.apiUrl}/${id}`);
  }
}

